:root {
  --bg-card: #f7f2e8;
  --bg-header: #2d4a2d;
  --bg-featured: #e8f0e0;
  --bg-item: #fdfaf4;
  --bg-footer: #3a3220;
  --color-text-primary: #1e2d1e;
  --color-text-secondary: #5a6e4a;
  --color-text-light: #f0ead6;
  --color-text-muted: #8a7d60;
  --color-accent-green: #4a7c4a;
  --color-border: #c8b890;
  --color-border-dark: #5a7a5a;
  --status-thriving-bg: #c8e6c0;
  --status-thriving-text: #1b5e20;
  --status-flowering-bg: #fce4ec;
  --status-flowering-text: #880e4f;
  --status-dormant-bg: #ffe0b2;
  --status-dormant-text: #bf360c;
}

.inventory-card {
  width: 460px;
  background-color: var(--bg-card);
  border: 2px solid var(--color-border);
  border-radius: 8px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.card-header {
  background-color: var(--bg-header);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
  border-bottom: 2px solid var(--color-border);
}

.header-left {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.facility-tag {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.14em;
  color: var(--color-border);
  text-transform: uppercase;
}

.card-title {
  font-size: 16px;
  font-weight: 700;
  color: var(--color-text-light);
  margin: 0;
  letter-spacing: 0.03em;
}

.date-stamp {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
  border: 1px solid var(--color-border-dark);
  border-radius: 4px;
  padding: 3px 7px;
}

.date-label {
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-border);
  text-transform: uppercase;
}

.date-value {
  font-size: 11px;
  font-weight: 700;
  color: var(--color-text-light);
}

.plant-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  padding: 8px;
}

.plant-item {
  background-color: var(--bg-item);
  border: 1px solid var(--color-border);
  border-radius: 6px;
  padding: 7px 9px;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.plant-item.featured {
  background-color: var(--bg-featured);
  border-color: var(--color-accent-green);
  border-width: 2px;
}

.plant-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.plant-icon {
  font-size: 18px;
  line-height: 1;
}

figcaption {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.plant-name {
  font-size: 11px;
  font-weight: 700;
  font-style: italic;
  color: var(--color-text-primary);
  line-height: 1.2;
}

.plant-origin {
  font-size: 9px;
  color: var(--color-text-muted);
  letter-spacing: 0.03em;
}

.plant-stats {
  display: flex;
  gap: 8px;
  margin-top: 1px;
}

.stat {
  font-size: 10px;
  color: var(--color-text-secondary);
}

.stat b {
  color: var(--color-text-primary);
  font-weight: 700;
}

.plant-badge {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  border-radius: 3px;
  padding: 2px 5px;
}

.status-thriving {
  background-color: var(--status-thriving-bg);
  color: var(--status-thriving-text);
}

.status-flowering {
  background-color: var(--status-flowering-bg);
  color: var(--status-flowering-text);
}

.status-dormant {
  background-color: var(--status-dormant-bg);
  color: var(--status-dormant-text);
}

.card-footer {
  background-color: var(--bg-footer);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 6px 14px;
  border-top: 2px solid var(--color-border);
}

.footer-meta {
  display: flex;
  gap: 10px;
}

.meta-item {
  font-size: 10px;
  color: var(--color-text-light);
  opacity: 0.85;
}

.curator-sig {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 1px;
}

.sig-label {
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--color-border);
  text-transform: uppercase;
}

.sig-name {
  font-size: 11px;
  font-weight: 700;
  font-style: italic;
  color: var(--color-text-light);
}
